SET @srp6_sql := IF(@srp6_ready,
'CREATE TABLE IF NOT EXISTS `alrowad_uni_rust`.`course_offering_minimum_enrollment_reviews` (
 `course_offering_minimum_enrollment_review_id` INT NOT NULL AUTO_INCREMENT, `semester_offering_request_id` INT NOT NULL, `course_offering_id` INT NOT NULL, `academic_year_id` INT NOT NULL, `semester_id` INT NOT NULL,
