 `status` VARCHAR(32) NOT NULL, `dean_recommendation` VARCHAR(16) NULL, `dean_user_id` INT NULL, `dean_notes` TEXT NULL, `dean_recommended_at` DATETIME NULL,
 `scientific_decision` VARCHAR(16) NULL, `scientific_user_id` INT NULL, `scientific_notes` TEXT NULL, `scientific_decided_at` DATETIME NULL,
 `course_offering_closure_request_id` INT NULL, `continued_at` DATETIME NULL, `cancelled_at` DATETIME NULL, `superseded_at` DATETIME NULL, `affected_registration_count` INT NULL,
 `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 PRIMARY KEY (`course_offering_minimum_enrollment_review_id`), UNIQUE KEY `uq_comer_request` (`semester_offering_request_id`), UNIQUE KEY `uq_comer_offering` (`course_offering_id`), UNIQUE KEY `uq_comer_closure` (`course_offering_closure_request_id`),
 KEY `idx_comer_term_status` (`academic_year_id`,`semester_id`,`status`), KEY `idx_comer_dean` (`dean_user_id`), KEY `idx_comer_scientific` (`scientific_user_id`),
 CONSTRAINT `chk_comer_snapshots` CHECK (`minimum_enrollment_snapshot`>0 AND `enrolled_count_snapshot`>=0 AND (`affected_registration_count` IS NULL OR `affected_registration_count`>=0)),
