 CONSTRAINT `fk_comer_scientific` FOREIGN KEY (`scientific_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`) ON UPDATE RESTRICT ON DELETE RESTRICT,
 CONSTRAINT `fk_comer_closure` FOREIGN KEY (`course_offering_closure_request_id`) REFERENCES `alrowad_uni_rust`.`course_offering_closure_requests` (`course_offering_closure_request_id`) ON UPDATE RESTRICT ON DELETE RESTRICT
