 CONSTRAINT `chk_srrpr_snapshot` CHECK ((`status`=''approved'' AND `registered_hours_before_approval` IS NOT NULL AND `replacement_hours_at_approval` IS NOT NULL AND `projected_hours_at_approval` IS NOT NULL AND `max_allowed_hours_at_approval` IS NOT NULL AND `remaining_hours_after_approval` IS NOT NULL) OR (`status`<>''approved'' AND `registered_hours_before_approval` IS NULL AND `replacement_hours_at_approval` IS NULL AND `projected_hours_at_approval` IS NULL AND `max_allowed_hours_at_approval` IS NULL AND `remaining_hours_after_approval` IS NULL)),
